import test from "node:test";
import assert from "node:assert/strict";
import { nameTooLong, MAX_NAME } from "../src/limits.js";

test("un nume de peste 80 de caractere este prea lung", () => {
  assert.equal(nameTooLong("a".repeat(MAX_NAME + 1)), true);
  assert.equal(nameTooLong("  Ana  "), false);
});
